package eit_acquisition_supervisor.EIT_Acquisition_Supervisor

import org.sireum._
import art._
import eit_acquisition_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait BatchAssessment_Api {
  def id: Art.BridgeId
  def batch_signal_Id : Art.PortId
  def batch_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var batch_facts: EIT_Acquisition_Supervisor.BatchFacts.Type = $

  def put_batch_facts(value : EIT_Acquisition_Supervisor.BatchFacts.Type) : Unit = {
    Contract(
      Modifies(batch_facts),
      Ensures(
        batch_facts == value
      )
    )
    Spec {
      batch_facts = value
    }

    Art.putValue(batch_facts_Id, EIT_Acquisition_Supervisor.BatchFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class BatchAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val batch_signal_Id : Art.PortId,
  val batch_facts_Id : Art.PortId) extends BatchAssessment_Api

@datatype class BatchAssessment_Operational_Api (
  val id: Art.BridgeId,
  val batch_signal_Id : Art.PortId,
  val batch_facts_Id : Art.PortId) extends BatchAssessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var batch_signal: EIT_Acquisition_Supervisor.BatchSignal.Type = $

  def get_batch_signal() : Option[EIT_Acquisition_Supervisor.BatchSignal.Type] = {
    Contract(
      Ensures(
        Res == Some(batch_signal)
      )
    )
    val value : Option[EIT_Acquisition_Supervisor.BatchSignal.Type] = Art.getValue(batch_signal_Id) match {
      case Some(EIT_Acquisition_Supervisor.BatchSignal_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port batch_signal.  Expecting 'EIT_Acquisition_Supervisor.BatchSignal_Payload' but received ${v}")
        None[EIT_Acquisition_Supervisor.BatchSignal.Type]()
      case _ => None[EIT_Acquisition_Supervisor.BatchSignal.Type]()
    }
    return value
  }
}
